package mz.bam.seeky.android;
import android.content.*;import android.database.*;import android.net.Uri;import android.os.ParcelFileDescriptor;import android.provider.OpenableColumns;import java.io.*;import java.util.*;
/** Read-only handles to explicit voice notes and recognised image text. */
public final class PlusFileProvider extends ContentProvider {
 public boolean onCreate(){return true;}
 static Uri voice(Context c,long id){return new Uri.Builder().scheme("content").authority(c.getPackageName()+".reading").appendPath("voice").appendPath(""+id).build();}
 static Uri ocr(Context c,String source,int part){return new Uri.Builder().scheme("content").authority(c.getPackageName()+".reading").appendPath("ocr").appendQueryParameter("source",source).appendQueryParameter("part",""+part).build();}
 File resolve(Uri uri)throws Exception{List<String> parts=uri.getPathSegments();if(parts.size()==2&&parts.get(0).equals("voice")){try(PlusStore db=new PlusStore(getContext())){List<StudyStore.Row> rows=db.rows("voice_notes","id=?",new String[]{parts.get(1)},null,1);if(rows.isEmpty())throw new FileNotFoundException();File file=new File(rows.get(0).s("path")).getCanonicalFile();if(!DiskWalker.inside(new File(getContext().getFilesDir(),"voice-notes").getCanonicalFile(),file)||!file.isFile())throw new FileNotFoundException();return file;}}if(parts.size()==1&&parts.get(0).equals("ocr")){String source=uri.getQueryParameter("source");if(source==null||source.length()>4096)throw new FileNotFoundException();StudyStore.Row row=OcrCache.row(getContext(),source,Integer.parseInt(uri.getQueryParameter("part")));if(row==null)throw new FileNotFoundException();File dir=new File(getContext().getCacheDir(),"ocr-text");dir.mkdirs();File file=new File(dir,ReaderStore.digest(source+uri.getQueryParameter("part")+row.s("value"))+".txt");if(!file.isFile()){File temp=new File(dir,UUID.randomUUID()+".part");try(FileOutputStream out=new FileOutputStream(temp)){out.write(row.s("value").getBytes("UTF-8"));}java.nio.file.Files.move(temp.toPath(),file.toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);}return file;}throw new FileNotFoundException();}
 public ParcelFileDescriptor openFile(Uri uri,String mode)throws FileNotFoundException{if(!mode.equals("r"))throw new FileNotFoundException();try{return ParcelFileDescriptor.open(resolve(uri),ParcelFileDescriptor.MODE_READ_ONLY);}catch(Exception e){throw new FileNotFoundException("Nota ou texto indisponível.");}}
 public String getType(Uri uri){return uri.getPathSegments().contains("voice")?"audio/wav":"text/plain";}
 public Cursor query(Uri uri,String[] projection,String s,String[] args,String sort){try{File file=resolve(uri);String[] cols=projection==null?new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE}:projection;MatrixCursor cursor=new MatrixCursor(cols);Object[] row=new Object[cols.length];for(int i=0;i<cols.length;i++)row[i]=cols[i].equals(OpenableColumns.DISPLAY_NAME)?getType(uri).equals("audio/wav")?"Seeky_Nota_de_Voz.wav":"Seeky_Texto_OCR.txt":cols[i].equals(OpenableColumns.SIZE)?file.length():null;cursor.addRow(row);return cursor;}catch(Exception e){return null;}}
 public Uri insert(Uri u,ContentValues v){throw new UnsupportedOperationException();}public int update(Uri u,ContentValues v,String w,String[] a){throw new UnsupportedOperationException();}public int delete(Uri u,String w,String[] a){throw new UnsupportedOperationException();}
}
